{
    "name": "bundesrat-plenarprotokolle",
    "title": "The Bundesrat corpus: A dataset of political discourse in the German Federal Council",
    "version": "v1",
    "description": "Structured, speaker-attributed speech corpus from German Bundesrat (Federal Council) plenary sessions, session 1 onward (1949\u2013present). Members represent the 16 German Bundesl\u00e4nder, not parties. CC-BY 4.0.",
    "licenses": [
        {
            "name": "CC-BY-4.0",
            "title": "Creative Commons Attribution 4.0 International",
            "path": "https://creativecommons.org/licenses/by/4.0/"
        }
    ],
    "resources": [
        {
            "name": "sessions",
            "path": "sessions.parquet",
            "mediatype": "application/vnd.apache.parquet",
            "description": "One row per plenary session.",
            "schema": {
                "primaryKey": [
                    "session_id"
                ],
                "fields": [
                    {
                        "name": "session_id",
                        "type": "string",
                        "description": "Unique session key, e.g. 'Session_0941'."
                    },
                    {
                        "name": "session",
                        "type": "integer",
                        "description": "Continuous Bundesrat session number (1949 = 1, no Wahlperiode)."
                    },
                    {
                        "name": "date_iso",
                        "type": "date",
                        "description": "Session date (YYYY-MM-DD)."
                    },
                    {
                        "name": "meeting_city",
                        "type": "string",
                        "description": "City the sitting was held in: 'Bonn' up to 1999, 'Berlin' from 2000.
